<x-result.layout :title="$competition->name" :noindex="$preview ?? false">
    @if($preview ?? false)<div class="rr-preview"><strong>{{ __('result.preview_title') }}</strong><span>{{ __('result.preview_hint') }}</span></div>@endif
    <a class="rr-back" href="{{ ($preview ?? false) ? route('eys.competitions.show', $competition) : route('result.index') }}">← {{ ($preview ?? false) ? __('result.back_to_eys') : __('result.back') }}</a>
    <header class="rr-hero"><div class="rr-kicker">{{ $competition->institution?->name }}</div><h1 class="rr-title">{{ $competition->name }}</h1><p class="rr-lead">{{ $competition->subject }}</p><div class="rr-stats"><div class="rr-stat"><strong>{{ $competition->categories->count() }}</strong>{{ __('result.categories') }}</div><div class="rr-stat"><strong>{{ $participantCount }}</strong>{{ __('result.participants') }}</div><div class="rr-stat"><strong>{{ $photoCount }}</strong>{{ __('result.photos') }}</div></div></header>
    <nav class="rr-tabs" aria-label="{{ __('result.result_sections') }}"><a href="#results">{{ __('result.results') }}</a><a href="#information">{{ __('result.information') }}</a><a href="#participants">{{ __('result.awarded_participants') }}</a><a href="#statistics">{{ __('result.statistics') }}</a></nav>
    <section id="results" class="rr-section"><h2>{{ __('result.results') }}</h2>
        @forelse($competition->categories as $category)
            @php $categoryResults = $resultsByCategory->get($category->id, collect())->sortBy('rank'); @endphp
            @if($categoryResults->isNotEmpty())<h3>{{ $category->name }}</h3><div class="rr-gallery">@foreach($categoryResults as $result)<article class="rr-work"><img src="{{ ($preview ?? false) ? route('eys.competitions.results.photos.show', [$competition, $result->photo]) : route('result.photos.show', $result->photo) }}" alt="{{ __('result.awarded_photo_alt', ['category' => $category->name]) }}"><div class="rr-work-body"><div class="rr-award">{{ $result->awards->map(fn ($award) => $award->categoryAward->awardReference?->name ?: $award->categoryAward->special_award_text)->filter()->join(' · ') }}</div><h3>{{ trim($result->photo->submission->entry->user->first_name.' '.$result->photo->submission->entry->user->last_name) }}</h3><p>#{{ $result->rank }} · {{ $category->name }}</p></div></article>@endforeach</div>@endif
        @empty<div class="rr-empty">{{ __('result.no_awards') }}</div>@endforelse
    </section>
    <section id="information" class="rr-section"><h2>{{ __('result.information') }}</h2><div class="rr-table-wrap"><table class="rr-table"><tbody><tr><th>{{ __('result.institution') }}</th><td>{{ $competition->institution?->name }}</td></tr><tr><th>{{ __('result.type') }}</th><td>{{ $competition->competitionType?->name }}</td></tr><tr><th>{{ __('result.result_date') }}</th><td>{{ $competition->results_published_at?->format('d.m.Y H:i') ?: __('result.not_published_yet') }}</td></tr><tr><th>{{ __('result.publication_version') }}</th><td>v{{ max(1, $competition->results_publication_version) }}</td></tr><tr><th>{{ __('result.evaluation_round') }}</th><td>{{ $round->name }}</td></tr></tbody></table></div></section>
    @if(!($preview ?? false) && isset($publicationHistory) && $publicationHistory->isNotEmpty())
        <section class="rr-section" id="publication-history"><h2>Yayın ve düzeltme geçmişi</h2><div class="rr-table-wrap"><table class="rr-table"><thead><tr><th>Versiyon</th><th>Yayın tarihi</th><th>Yayın notu</th><th>Düzeltme notu</th></tr></thead><tbody>@foreach($publicationHistory as $publication)<tr><td>v{{ $publication->version }}</td><td>{{ $publication->published_at->format('d.m.Y H:i') }}</td><td>{{ $publication->publication_note ?: '—' }}</td><td>{{ $publication->correction_note ?: '—' }}</td></tr>@endforeach</tbody></table></div></section>
    @endif
    <section id="participants" class="rr-section"><h2>{{ __('result.awarded_participants') }}</h2><div class="rr-table-wrap"><table class="rr-table"><thead><tr><th>{{ __('result.participant') }}</th></tr></thead><tbody>@foreach($participants as $participant)<tr><td>{{ trim($participant->first_name.' '.$participant->last_name) }}</td></tr>@endforeach</tbody></table></div></section>
    <section id="statistics" class="rr-section"><h2>{{ __('result.statistics') }}</h2><div class="rr-stats"><div class="rr-stat"><strong>{{ $participantCount }}</strong>{{ __('result.total_participants') }}</div><div class="rr-stat"><strong>{{ $photoCount }}</strong>{{ __('result.total_photos') }}</div><div class="rr-stat"><strong>{{ $resultsByCategory->flatten(1)->count() }}</strong>{{ __('result.awarded_works') }}</div></div></section>
</x-result.layout>
